#!/bin/zsh
# V2.1 fix window, lane E (owner 2026-10-15: "run the full suite locally on Linux in Docker; keep goe-* working"):
# `python3 -m unittest discover -s tests` — all of it or a named subset — in the Linux guest of Docker Desktop's VM on a
# macOS host, on a tree exported by `git archive`, in one discarded container. Do not edit this file while it runs.
#
#   zsh validation/v21/sandbox/linux_suite.sh OUT_DIR [COMMIT] [-- MODULE ...]
#
#   OUT_DIR  must not exist; receives the evidence (below). Everything else the run writes lives in the container.
#   COMMIT   what to test (default HEAD of the repo holding this script). The tree is `git archive COMMIT`, streamed
#            through the container's stdin and extracted to a tmpfs there: the host's tree is never mounted or written,
#            and the 1.4 GB archive never touches the host's disk (a file mount is 48 s faster, measured; the host disk
#            was at 0.5-2 GiB free while other lanes ran, so no file).
#   MODULE   unittest modules named as `discover -s tests` names them (v2.test_x, test_meta, v2.p4.test_y); none = all.
#
# One container (name aisef-linux-suite-<pid>): --rm --init --network none --user 1000:1000 --cap-drop ALL, pids,
# memory and CPUs bounded. Profile X1 (default) is linux_guest.sh's: Docker's seccomp filter off and system paths
# unmasked, which is what bubblewrap needs on this kernel (SANDBOX-LINUX.md §3); SUITE_PROFILE=hardened keeps Docker's
# defaults. Only local images: the measure image, and the procps `ps` copied out of postgres:16.15 with `docker run --rm
# ... cat` (the measure image has none); it pulls, builds, stops and removes nothing but its own container. Containers
# it did not start (goe-postgres-1, goe-valkey-1) are listed and sampled with `docker stats`, never touched. Never runs
# opencode (the guest has none) and calls no provider.
#
# Inside: the tree is a git repository again (the suite reads history: tags, the bench base commits): `git init`, a
# `git fetch` of OUT_DIR/history.bundle (this repository's refs, mounted read-only), HEAD on COMMIT, the index set from
# it, the working tree left as the archive made it — `git status` there is the proof that the tree is COMMIT. The suite
# then runs as CI runs it (tests.yml: validation/v2/owned_run.py around `unittest discover -s tests`), in `env -i`:
# HOME, XDG_*, TMPDIR fresh under the tmpfs, PATH /usr/local/bin:/usr/bin:/bin, LANG=C.UTF-8, no PYTHONPATH, no AISEF_*
# variable — so what needs Docker (AISEF_TEST_DOCKER), a real client or Node skips, as it does on CI.
# A container holds a dozen processes, a host hundreds: v2.p4.test_mutation_safety MUT_SAFE_6 builds "the catastrophic
# mutant" and asserts it reports more than 50 processes of the host. The entry shell therefore starts SUITE_FILLER idle
# `sleep` processes the checks did not start (the authority must never signal them, as on a real host); 0 shows it red.
#
# Output in OUT_DIR:
#   environment.txt  host, docker, guest (kernel, python, git, bwrap, ps, caps, limits, no opencode), the tree check
#   suite.txt        the unittest log (stderr of the run, -v: one line per test)
#   stdout.txt       the container's stdout: stage markers and the blocks below, between @@SUITE-*-BEGIN/END
#   summary.json     tests, failures, errors, skips with reasons, seconds per module, 30 slowest tests, max RSS;
#                    "complete": false when the run ended before the suite did (rewritten at every module)
#   owned.json       validation/v2/owned_run.py's measurement of the process range (owned / escaped processes)
#   vm.log           loadavg and MemAvailable of the VM, the container's cgroup memory and CPU, every 10 s
#   stats.txt        `docker stats --no-stream` of every running container, every SUITE_STATS_S s
#   result.txt       exit code, wall time, counts, slowest modules, the load — the text this script prints last
#   commands.txt     the exact docker command; archive.sha256; guest-entry.sh and driver.py are what ran in it.
#   history.bundle (0.2 GB) is removed at the end — its sha256 is in environment.txt — unless SUITE_KEEP_INPUTS=1.
# Exit status: the container's (0 only when the suite passed and no owned process outlived it; 124 timed out), or 2
# when there is no result.
#
# Knobs (environment), defaults in brackets:
#   SUITE_PROFILE [X1]  SUITE_CPUS [4]  SUITE_MEM [5g, tmpfs included]  SUITE_TMPFS [4g; the tree and history are 1.6 GB]
#   SUITE_PIDS [2048]  SUITE_TIMEOUT [10800 s, inside]  SUITE_OWNED [1: owned_run.py]  SUITE_FILLER [100]
#   SUITE_STATS_S [10]  SUITE_KEEP_INPUTS [0]  SUITE_PROCPS_DIR [a dir holding ps and libproc2.so.0; default: copied
#   into OUT_DIR/procps]  SUITE_IMAGE [aisef-sandbox-measure].
set -u
HERE=${0:A:h}
REPO=$(git -C $HERE rev-parse --show-toplevel) || { print "not inside a git repository"; exit 2 }
OUT=${1:?OUT_DIR}; shift
COMMIT=HEAD
if [[ $# -gt 0 && $1 != -- ]]; then COMMIT=$1; shift; fi
[[ ${1:-} == -- ]] && shift
MODULES=("$@")
SHA=$(git -C $REPO rev-parse --verify -q "$COMMIT^{commit}") || { print "no such commit: $COMMIT"; exit 2 }
[[ ! -e $OUT ]] || { print "OUT_DIR exists"; exit 2 }

IMG=${SUITE_IMAGE:-aisef-sandbox-measure}; PROCPS_IMG=postgres:16.15
PROFILE=${SUITE_PROFILE:-X1}; CPUS=${SUITE_CPUS:-4}; MEM=${SUITE_MEM:-5g}; PIDS=${SUITE_PIDS:-2048}
TMPFS=${SUITE_TMPFS:-4g}; TIMEOUT=${SUITE_TIMEOUT:-10800}; OWNED=${SUITE_OWNED:-1}; STATS_S=${SUITE_STATS_S:-10}
[[ $PROFILE == X1 || $PROFILE == hardened ]] || { print "SUITE_PROFILE must be X1 or hardened"; exit 2 }
docker image inspect $IMG > /dev/null 2>&1 || { print "local image $IMG missing (this script pulls and builds nothing)"; exit 2 }
docker image inspect $PROCPS_IMG > /dev/null 2>&1 || { print "local image $PROCPS_IMG missing"; exit 2 }
[[ -z $(docker ps -q --filter name=aisef-linux-suite-) ]] || { print "another aisef-linux-suite container is running"; exit 2 }
FREE_KB=$(df -k $OUT:h | awk 'NR==2{print $4}')
(( FREE_KB > 1024 * 1024 )) || { print "less than 1 GiB free for OUT_DIR (the history bundle is 0.2 GB)"; exit 2 }
mkdir -p $OUT

NAME=aisef-linux-suite-$$
# the guest's multiarch lib directory: ps needs libproc2.so.0 where the dynamic loader looks
LIBDIR=/usr/lib/$(docker run --rm --network none --cap-drop ALL --entrypoint uname $IMG -m)-linux-gnu
PROCPS=${SUITE_PROCPS_DIR:-$OUT/procps}
if [[ ! -f $PROCPS/ps || ! -f $PROCPS/libproc2.so.0 ]]; then
  mkdir -p $PROCPS
  docker run --rm --network none --cap-drop ALL --entrypoint cat $PROCPS_IMG /usr/bin/ps > $PROCPS/ps || exit 2
  docker run --rm --network none --cap-drop ALL --entrypoint cat $PROCPS_IMG $LIBDIR/libproc2.so.0 > $PROCPS/libproc2.so.0 || exit 2
  chmod 755 $PROCPS/ps
fi
# no delta search, light compression: the bundle only carries history, and the default search cost 50 s of CPU
git -C $REPO -c pack.window=0 -c pack.compression=1 -c pack.threads=2 bundle create $OUT/history.bundle --all \
  > $OUT/bundle.log 2>&1 || { print "bundle failed"; exit 2 }
cp $HERE/linux_suite_guest.py $OUT/driver.py

# what runs inside: stdin is the tar of COMMIT
cat > $OUT/guest-entry.sh <<'ENTRY'
#!/bin/sh
W=/work; T=$W/tree
mark() { echo "@@SUITE-STAGE $1 $(date +%s)"; }
mkdir -p $T $W/home $W/tmp $W/xdg/config $W/xdg/data $W/xdg/state $W/xdg/cache
echo "@@SUITE-ENV-BEGIN"
echo "kernel $(uname -srvm)"; echo "debian $(cat /etc/debian_version)"
echo "uid $(id -u) gid $(id -g) HOME $HOME user $(id -un)"
grep -E "^(Seccomp|NoNewPrivs|CapEff|CapBnd):" /proc/self/status | tr "\n" " "; echo
echo "max_user_namespaces $(cat /proc/sys/user/max_user_namespaces)"
python3 -VV; git --version; bwrap --version; ps --version
command -v opencode || echo "opencode: absent from the guest"
echo "nproc $(nproc); VM $(grep -E '^(MemTotal|MemAvailable):' /proc/meminfo | tr -s ' ' | tr '\n' ' ')"
echo "cgroup memory.max $(cat /sys/fs/cgroup/memory.max 2>/dev/null) cpu.max $(cat /sys/fs/cgroup/cpu.max 2>/dev/null) pids.max $(cat /sys/fs/cgroup/pids.max 2>/dev/null)"
echo "ulimit -n $(ulimit -n)"; df -h $W | tail -1
bwrap --unshare-user --unshare-pid --die-with-parent --ro-bind / / --proc /proc true && echo "bwrap starts: yes" || echo "bwrap starts: no"
echo "@@SUITE-ENV-END"
mark extract
tar -xf - -C $T || { echo "@@SUITE-FAIL extract"; exit 70; }
mark git
cd $T || exit 70
(
  export HOME=$W/home GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_NOSYSTEM=1
  git init -q -b suite-guest . && git fetch -q --no-tags /opt/suite/history.bundle '+refs/*:refs/*' \
    && git update-ref --no-deref HEAD "$COMMIT" && git reset -q || { echo "@@SUITE-FAIL git"; exit 71; }
  echo "@@SUITE-TREE-BEGIN"
  echo "HEAD $(git rev-parse HEAD) tree $(git rev-parse 'HEAD^{tree}') (wanted $COMMIT)"
  echo "refs $(git for-each-ref | wc -l), tags $(git tag | wc -l); files in the tree $(find . -path ./.git -prune -o ! -type d -print | wc -l)"
  echo "paths differing from COMMIT: $(git status --porcelain | wc -l)"; git status --porcelain | head -20
  echo "@@SUITE-TREE-END"
) || exit $?
( while :; do
    echo "$(date +%s) load $(cut -d' ' -f1-3 /proc/loadavg) vm_avail_kb $(awk '/^MemAvailable:/{print $2}' /proc/meminfo)" \
         "cg_mem_bytes $(cat /sys/fs/cgroup/memory.current 2>/dev/null) cg_cpu_usec $(awk '/^usage_usec/{print $2}' /sys/fs/cgroup/cpu.stat 2>/dev/null)"
    sleep 10
  done > $W/vm.log ) &
SAMPLER=$!
i=0; while [ $i -lt "$SUITE_FILLER" ]; do sleep $((SUITE_TIMEOUT + 600)) < /dev/null > /dev/null 2>&1 & i=$((i + 1)); done
echo "@@SUITE-FILLER $SUITE_FILLER idle processes started; $(ls /proc | grep -c '^[0-9]') processes in the guest"
mark suite
CLEAN="env -i PATH=/usr/local/bin:/usr/bin:/bin HOME=$W/home XDG_CONFIG_HOME=$W/xdg/config XDG_DATA_HOME=$W/xdg/data \
  XDG_STATE_HOME=$W/xdg/state XDG_CACHE_HOME=$W/xdg/cache TMPDIR=$W/tmp LANG=C.UTF-8 USER=op LOGNAME=op PYTHONDONTWRITEBYTECODE=1"
if [ "$SUITE_OWNED" = 1 ] && [ -f validation/v2/owned_run.py ]; then
  timeout -k 30 "$SUITE_TIMEOUT" $CLEAN python3 -B -P validation/v2/owned_run.py --out $W/owned.json -- \
    python3 -B /opt/suite/driver.py --summary $W/summary.json "$@"
else
  timeout -k 30 "$SUITE_TIMEOUT" $CLEAN python3 -B /opt/suite/driver.py --summary $W/summary.json "$@"
fi
code=$?
mark end
kill $SAMPLER 2>/dev/null
echo "@@SUITE-EXIT $code"
echo "@@SUITE-DF $(df -k $W | tail -1)"
echo "@@SUITE-SUMMARY-BEGIN"; cat $W/summary.json 2>/dev/null; echo "@@SUITE-SUMMARY-END"
echo "@@SUITE-OWNED-BEGIN"; cat $W/owned.json 2>/dev/null; echo "@@SUITE-OWNED-END"
echo "@@SUITE-VM-BEGIN"; cat $W/vm.log 2>/dev/null
echo "final memory.peak $(cat /sys/fs/cgroup/memory.peak 2>/dev/null) cpu.stat $(tr '\n' ' ' < /sys/fs/cgroup/cpu.stat 2>/dev/null)"
echo "@@SUITE-VM-END"
exit $code
ENTRY

BASE=(--rm --init -i --name $NAME --network none --user 1000:1000 --cap-drop ALL --pids-limit $PIDS --memory $MEM --cpus $CPUS
      --tmpfs /work:rw,exec,nosuid,nodev,size=$TMPFS,uid=1000,gid=1000,mode=0700 -w /work
      -e COMMIT=$SHA -e SUITE_TIMEOUT=$TIMEOUT -e SUITE_OWNED=$OWNED -e SUITE_FILLER=${SUITE_FILLER:-100}
      -v $PROCPS/ps:/usr/local/bin/ps:ro -v $PROCPS/libproc2.so.0:$LIBDIR/libproc2.so.0:ro
      -v $OUT/history.bundle:/opt/suite/history.bundle:ro -v $OUT/guest-entry.sh:/opt/suite/entry.sh:ro
      -v $OUT/driver.py:/opt/suite/driver.py:ro)
X1=(--security-opt seccomp=unconfined --security-opt systempaths=unconfined)
[[ $PROFILE == X1 ]] && F=($X1) || F=()
load() { print -r -- "host load average $(sysctl -n vm.loadavg) at $(date '+%Y-%m-%dT%H:%M:%S%z')"; }

{
  print "== host: $(uname -srm); $(sw_vers -productName 2>/dev/null) $(sw_vers -productVersion 2>/dev/null)"; load
  print "== docker version"; docker version
  docker info --format 'guest: {{.OperatingSystem}}; kernel {{.KernelVersion}}; {{.NCPU}} CPUs; {{.MemTotal}} bytes; cgroup v{{.CgroupVersion}}; security {{.SecurityOptions}}'
  print "== other containers running in the same VM (not started by this script; never touched)"
  docker ps --format '{{.ID}} {{.Names}} {{.Image}} {{.Status}}'
  docker image inspect $IMG --format "image: $IMG {{.Id}} created {{.Created}} {{.Os}}/{{.Architecture}}"
  docker image inspect $PROCPS_IMG --format "procps source image: $PROCPS_IMG {{.Id}} {{.Os}}/{{.Architecture}}"
  print "procps: $(shasum -a 256 $PROCPS/ps $PROCPS/libproc2.so.0 | awk '{print $1}' | tr '\n' ' ')"
  print "commit: $SHA tree $(git -C $REPO rev-parse "$SHA^{tree}")"
  print "bundle: $(shasum -a 256 $OUT/history.bundle | cut -c1-64) $(wc -c < $OUT/history.bundle | tr -d ' ') bytes"
  print "profile: $PROFILE; flags: ${BASE[*]} ${F[*]}"
  print "filler processes: ${SUITE_FILLER:-100}"
  print "modules: ${MODULES[*]:-<all: discover -s tests>}"
} > $OUT/environment.txt 2>&1
print -r -- "git archive --format=tar $SHA | docker run ${BASE[*]} ${F[*]} $IMG sh /opt/suite/entry.sh ${MODULES[*]}" > $OUT/commands.txt

( while :; do
    print -r -- "$(date +%s) $(docker stats --no-stream --format '{{.Name}} cpu={{.CPUPerc}} mem={{.MemUsage}} pids={{.PIDs}}' 2>/dev/null | tr '\n' ';')" >> $OUT/stats.txt
    sleep $STATS_S
  done ) &
SAMPLER=$!
trap 'kill $SAMPLER 2>/dev/null' EXIT
trap 'docker stop -t 20 $NAME > /dev/null 2>&1; exit 130' INT TERM    # only the container this script named

T0=$(date +%s)
print "$(load)" >> $OUT/commands.txt
git -C $REPO archive --format=tar $SHA | tee >(shasum -a 256 | cut -c1-64 > $OUT/archive.sha256) \
  | docker run $BASE $F $IMG sh /opt/suite/entry.sh "${MODULES[@]}" > $OUT/stdout.txt 2> $OUT/suite.txt
CODE=${pipestatus[3]}
WALL=$(( $(date +%s) - T0 ))
for i in {1..60}; do [[ -s $OUT/archive.sha256 ]] && break; sleep 0.5; done
print "exit $CODE in $WALL s; $(load)" >> $OUT/commands.txt
kill $SAMPLER 2>/dev/null

section() { awk -v b="@@SUITE-$1-BEGIN" -v e="@@SUITE-$1-END" '$0==b{f=1;next} $0==e{f=0} f' $OUT/stdout.txt; }
{ print "== guest view (the container's own report)"; section ENV; print "== the tree in the guest"; section TREE
  print "archive: git archive --format=tar $SHA sha256 $(cat $OUT/archive.sha256 2>/dev/null)"
  grep '^@@SUITE-DF' $OUT/stdout.txt
} >> $OUT/environment.txt
section SUMMARY > $OUT/summary.json; section OWNED > $OUT/owned.json; section VM > $OUT/vm.log

# the report: what ran, how long, what it cost the VM
python3 -I - $OUT $CODE $WALL $NAME $CPUS <<'PY' | tee $OUT/result.txt
import json, pathlib, re, sys
out, code, wall, name, cpus = pathlib.Path(sys.argv[1]), int(sys.argv[2]), int(sys.argv[3]), sys.argv[4], sys.argv[5]
def load(n):
    try:
        return json.loads((out / n).read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return None
s, o = load("summary.json"), load("owned.json")
print(f"container exit {code}; wall {wall} s ({wall / 60:.1f} min)")
if s is None:
    print("NO RESULT: the run left no summary.json (see suite.txt and stdout.txt)")
else:
    if not s["complete"]:
        print("INCOMPLETE: the run ended before the suite did (killed, timed out or died); numbers are up to the last module")
    print(f"discovered {s['discovered']}, ran {s['ran']}, failures {len(s['failures'])}, errors {len(s['errors'])}, "
          f"skipped {s['skipped']}, expected failures {s['expected_failures']}, unexpected successes {len(s['unexpected_successes'])}")
    print(f"load {s['load_s']} s, run {s['run_s']} s, max RSS driver {s['driver_maxrss_kb'] // 1024} MiB, "
          f"largest child {s['children_maxrss_kb'] // 1024} MiB")
    for k in ("failures", "errors", "unexpected_successes"):
        for t in s[k]:
            print(f"  {k[:-1] if k != 'unexpected_successes' else 'unexpected success'}: {t}")
    print("skips by reason:")
    for r, n in list(s["skips_by_reason"].items())[:15]:
        print(f"  {n:5d}  {r}")
    print("slowest modules:")
    for m, v in sorted(s["modules"].items(), key=lambda kv: -kv[1]["seconds"])[:12]:
        print(f"  {v['seconds']:8.1f} s  {v['tests']:5d} tests  {v['skipped']:4d} skipped  {m}")
if o is not None:
    print(f"owned processes: at exit {o['owned_at_exit']}, after {o['owned_after']}, escaped {len(o['escaped'])}, "
          f"released empty {o['released_empty']}, harness orphans {o['harness_orphans_before']} -> {o['harness_orphans_after']}")
# load: the container (docker stats) and the VM (loadavg, MemAvailable from inside)
cpu = mem = 0.0
others = {}
try:
    for line in (out / "stats.txt").read_text(encoding="utf-8").splitlines():
        for item in line.partition(" ")[2].split(";"):
            m = re.match(r"(\S+) cpu=([\d.]+)% mem=([\d.]+)(\w+) / ", item)
            if not m:
                continue
            v = float(m[3]) * {"B": 1, "KiB": 1 << 10, "MiB": 1 << 20, "GiB": 1 << 30}.get(m[4], 1)
            if m[1] == name:
                cpu, mem = max(cpu, float(m[2])), max(mem, v)
            else:
                c, mm = others.get(m[1], (0.0, 0.0))
                others[m[1]] = (max(c, float(m[2])), max(mm, v))
except OSError:
    pass
print(f"docker stats: suite container peak CPU {cpu:.0f}% (of {int(float(cpus) * 100)}%), peak memory {mem / (1 << 20):.0f} MiB")
for n, (c, mm) in sorted(others.items()):
    print(f"  other container {n}: peak CPU {c:.1f}%, peak memory {mm / (1 << 20):.0f} MiB")
try:
    rows = [r.split() for r in (out / "vm.log").read_text(encoding="utf-8").splitlines() if " load " in r]
    if rows:
        print(f"VM (sampled inside): load1 max {max(float(r[2]) for r in rows):.1f}, "
              f"MemAvailable min {min(int(r[6]) for r in rows) // 1024} MiB over {len(rows)} samples")
    peak = re.search(r"final memory\.peak (\d+)", (out / "vm.log").read_text(encoding="utf-8"))
    cpu_s = re.search(r"usage_usec (\d+)", (out / "vm.log").read_text(encoding="utf-8"))
    if peak and cpu_s:
        print(f"cgroup: memory.peak {int(peak[1]) // (1 << 20)} MiB, CPU time {int(cpu_s[1]) / 1e6:.0f} s")
except (OSError, ValueError, IndexError):
    pass
PY
[[ ${SUITE_KEEP_INPUTS:-0} == 1 ]] || rm -f $OUT/history.bundle
print "done: $OUT"
[[ -s $OUT/summary.json ]] || { [[ $CODE -ne 0 ]] && exit $CODE; exit 2 }
exit $CODE
